+#timeline:has(.event)::before{content:"";position:absolute;top:25px;bottom:0;left:calc(var(--time-width) + var(--timeline-gap) + 4px);width:1px;background:linear-gradient(to bottom,rgba(59,130,246,.5),rgba(255,255,255,.1),transparent);pointer-events:none}
+.memory .event{position:relative;grid-template-columns:var(--time-width) 8px minmax(0,1fr);gap:var(--timeline-gap);padding:0 0 24px;align-items:start}
+.memory .event time{padding-top:20px;text-align:right;color:#6b7280;font:12px/1.6 ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;overflow-wrap:anywhere}
+.memory .event-dot{width:8px;height:8px;margin-top:25px;border-radius:50%;background:#60a5fa;box-shadow:0 0 10px rgba(96,165,250,.8);z-index:1}
+.memory .event article{min-width:0;padding:20px;background:rgba(255,255,255,.02);backdrop-filter:blur(24px);-webkit-backdrop-filter:blur(24px);border:1px solid rgba(255,255,255,.05);border-radius:12px;box-shadow:inset 0 1px 0 rgba(255,255,255,.05);transition:all .2s ease;overflow-wrap:anywhere}
+.memory .event article:hover{border-color:rgba(255,255,255,.15);background:rgba(255,255,255,.04)}
+.memory .event article>.eyebrow{margin:0 0 8px;font-size:10px;letter-spacing:.1em;text-transform:uppercase;color:#60a5fa;font-weight:600}
+.memory .event h3{margin:0 0 6px;font-size:18px;font-weight:500;color:#f3f4f6}
+.memory .event article>p:not(.eyebrow){font-size:14px;color:#9ca3af;line-height:1.625}
+.memory .event details{font-size:12px;color:#9ca3af}
+.memory .event summary{cursor:pointer}
+.memory .event pre{background:rgba(0,0,0,.4);border:1px solid rgba(255,255,255,.05);border-radius:8px;color:#9ca3af}
+#timeline>p{font-size:14px;color:#9ca3af}
+@media(max-width:720px){.memory{padding:40px 16px 72px}#timeline{--time-width:70px;--timeline-gap:12px}}
+@media(prefers-reduced-motion:reduce){.memory .event article,.memory .report-actions button{transition:none}}
"}

